'use strict';

const CODES = { cyan: 36, yellow: 33, red: 31 };
const LEVEL_COLOR = { info: 'cyan', warn: 'yellow', error: 'red' };

function supportsColor(stream = process.stdout) {
  const env = process.env;
  if ('NO_COLOR' in env) return false;
  if ('FORCE_COLOR' in env) return env.FORCE_COLOR !== '0';
  if (env.TERM === 'dumb') return false;
  return Boolean(stream && stream.isTTY);
}

function paint(color, text) {
  return supportsColor() ? `\u001b[${CODES[color]}m${text}\u001b[39m` : text;
}

function formatLine(level, message) {
  const tag = `[${level.toUpperCase()}]`;
  const color = LEVEL_COLOR[level];
  return `${color ? paint(color, tag) : tag} ${message}`;
}

module.exports = { formatLine, supportsColor };
